member.example:
This sample shows how to call GetSigningCertificateAsync.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
SigningCertificates client = new AttestationClient(endpoint, credential).GetSigningCertificatesClient();

Response<JsonWebKeySet> response = await client.GetSigningCertificateAsync(null);

This sample shows how to call GetSigningCertificate.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
SigningCertificates client = new AttestationClient(endpoint, credential).GetSigningCertificatesClient();

Response<JsonWebKeySet> response = client.GetSigningCertificate(null);

This sample shows how to call GetSigningCertificateAsync and parse the result.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
SigningCertificates client = new AttestationClient(endpoint, credential).GetSigningCertificatesClient();

Response response = await client.GetSigningCertificateAsync(null, null);

JsonElement result = JsonDocument.Parse(response.ContentStream).RootElement;
Console.WriteLine(result.ToString());

This sample shows how to call GetSigningCertificate and parse the result.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
SigningCertificates client = new AttestationClient(endpoint, credential).GetSigningCertificatesClient();

Response response = client.GetSigningCertificate(null, null);

JsonElement result = JsonDocument.Parse(response.ContentStream).RootElement;
Console.WriteLine(result.ToString());
